        uint256 _amount
    ) external returns (string memory);

    function invest(
        string calldata _roleId,
        string calldata _poolId,
        uint256 _amount
    ) external;

    function withdrawRequest(
        string calldata _roleId,
        address _token,
        uint256 _amount
    ) external returns(bool _isWithdrawn);

    function withdrawPoolPaymentIntoVault(
        Request calldata _request,
        bytes32 _sigR,
        bytes32 _sigS,
        uint8 _sigV
    ) external;
