// @author cSigma Finance Inc., a Delaware company, for its Real World Credit tokenization protocol

pragma solidity 0.8.9;

import "@openzeppelin/contracts-upgradeable/access/AccessControlUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import "@openzeppelin/contracts/proxy/ERC1967/ERC1967Proxy.sol";
import "./CsigmaV2Pool.sol";
import "./CsigmaV2FundManager.sol";
import "./CsigmaV2StakingPool.sol";

error InvalidAddress(address _poolManager);
error InvalidPoolName(string _poolName);
error StakingPoolExist(address _pool);
/// @title AccessControl
/// @notice Interface to interact with the AccessControl functionalities of a contract
interface AccessControl {
    function pause() external;
    function unpause() external;
    function emergencyWithdraw(address _token, address _to, uint256 _amount) external;
    function grantRole(bytes32 role, address _account) external;
    function revokeRole(bytes32 role, address _account) external;
}
/// @title CsigmaV2Factory
/// @notice Contract to create and manage cSigma V2 pools
contract CsigmaV2Factory is
    Initializable,
    AccessControlUpgradeable,
    UUPSUpgradeable
{
    address public poolImplementation;
    address public fundManagerImplementation;
    address public stakingPoolImplementation;
    address public diamondV1;
    address public sigmaToken;
    address public chainalysis;
    mapping (address => bool) public isPoolManager;
    mapping (address => bool) public isWhitelistedToken;
    mapping (address => bool) public isStakingPoolCreated;
    mapping (string => bool) private isPoolNameUsed;
    address[] public pools;

    event PoolImplementationUpdated(address _prevImpl, address _newImpl);
    event FundManagerImplementationUpdated(address _prevImpl, address _newImpl);
    event StakingPoolImplementationUpdated(address _prevImpl, address _newImpl);
    event ChainalysisAddressUpdated(address _prevAddress, address _newAddress);
    event SigmaTokenAddressUpdated(address _prevAddress, address _newAddress); 
    event PoolTokenAdded(address _poolToken);
    event PoolTokenRemoved(address _poolToken);
    event PoolManagerAdded(address _poolManager);
    event PoolManagerRemoved(address _poolManager);
    event PoolCreated(
        address _pool,
        address indexed _poolManager,
        address _fundManager,
        address indexed _poolToken,
        address indexed _oracleManager,
        uint256 _poolAPY,
        uint256 _poolSize
    );
    event StakingPoolCreated(address indexed _stakingPool, address indexed _pool);
    event PoolManagerUpdated(address indexed _pool, address indexed _oldManager, address indexed _newManager);
    event PoolSizeUpdated(address indexed _pool, uint256 _oldValue, uint256 _newValue);
    event AdminTransferred(address _oldOwner, address _newOwner);

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    /// @notice Initializes the factory with the given parameters
    /// @param _admin The address of the admin
    /// @param _fundManagerImpl The address of the fund manager implementation
    /// @param _stakingPoolImpl The address of the staking pool implementation
    /// @param _poolImpl The address of the pool implementation
    /// @param _diamondV1 The address of the diamond V1 contract
    /// @param _sigmaToken The address of the sigma token
    /// @param _chainalysis The address of the chainalysis contract
    function initialize(
        address _admin,
        address _fundManagerImpl,
        address _stakingPoolImpl,
        address _poolImpl,
        address _diamondV1,
        address _sigmaToken,
        address _chainalysis
    )
        public
        initializer
    {
        __AccessControl_init();
        __UUPSUpgradeable_init();
        
        _grantRole(DEFAULT_ADMIN_ROLE, _admin);
        fundManagerImplementation = _fundManagerImpl;
        poolImplementation = _poolImpl;
        stakingPoolImplementation = _stakingPoolImpl;
        diamondV1 = _diamondV1;
        sigmaToken = _sigmaToken;
        chainalysis = _chainalysis;
    }

    /// @notice Returns the total number of pools created
    function totalPools() external view returns (uint256) {
        return pools.length;
    }

    /// @notice Updates the pool implementation address
    /// @param _newImpl The address of the new pool implementation
    function updatePoolImplementation(address _newImpl) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if(_newImpl == address(0)) {
            revert InvalidAddress(_newImpl);
        }
        emit PoolImplementationUpdated(poolImplementation, _newImpl);
        poolImplementation = _newImpl;
    }

    /// @notice Updates the fund manager implementation address
    /// @param _newImpl The address of the new fund manager implementation
    function updateFundManagerImplementation(address _newImpl) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if(_newImpl == address(0)) {
            revert InvalidAddress(_newImpl);
        }
        emit FundManagerImplementationUpdated(fundManagerImplementation, _newImpl);
        fundManagerImplementation = _newImpl;
    }

    /// @notice Updates the staking pool implementation address
    /// @param _newImpl The address of the new staking pool implementation
    function updateStakingPoolImplementation(address _newImpl) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if(_newImpl == address(0)) {
            revert InvalidAddress(_newImpl);
        }
        emit StakingPoolImplementationUpdated(stakingPoolImplementation, _newImpl);
        stakingPoolImplementation = _newImpl;
    }

    /// @notice Updates the chainalysis contract address
    /// @param _newAddr The address of the new chainalysis contract
    function updateChainalysisAddress(address _newAddr) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if(_newAddr == address(0)) {
            revert InvalidAddress(_newAddr);
        }
        emit ChainalysisAddressUpdated(chainalysis, _newAddr);
        chainalysis = _newAddr;
    }

    /// @notice Updates the sigma token address
    function updateSigmaTokenAddress(address _newAddr) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if(_newAddr == address(0)) {
            revert InvalidAddress(_newAddr);
        }
        emit SigmaTokenAddressUpdated(sigmaToken, _newAddr);
        sigmaToken = _newAddr;
    }

    /// @notice Adds a pool manager to the factory
    /// @param _poolManager The address of the pool manager
    function addPoolManager(address _poolManager) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if(_poolManager == address(0) || isPoolManager[_poolManager]) {
            revert InvalidAddress(_poolManager);
        }
        isPoolManager[_poolManager] = true;
        emit PoolManagerAdded(_poolManager);
    }

    /// @notice Removes a pool manager from the factory
    /// @param _poolManager The address of the pool manager
    function removePoolManager(address _poolManager) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if(!isPoolManager[_poolManager]) {
            revert InvalidAddress(_poolManager);
        }
        isPoolManager[_poolManager] = false;
        emit PoolManagerRemoved(_poolManager);
    }

    /// @notice Adds a token to the whitelist
    /// @param _token The address of the token
    function addTokenToWhitelist(address _token) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if(_token == address(0) || isWhitelistedToken[_token]) {
            revert InvalidAddress(_token);
        }
        isWhitelistedToken[_token] = true;
        emit PoolTokenAdded(_token);
    }

    /// @notice Removes a token from the whitelist
    /// @param _token The address of the token
    function removeTokenFromWhitelist(address _token) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if(!isWhitelistedToken[_token]) {
            revert InvalidAddress(_token);
        }
        isWhitelistedToken[_token] = false;
        emit PoolTokenRemoved(_token);
    }

    /// @notice Creates a new pool
    /// @param _poolName The name of the pool
    /// @param _poolSymbol The symbol of the pool
    /// @param _fundManagerLenderId The lender id of the fund manager
    /// @param _poolManager The address of the pool manager
    /// @param _poolToken The address of the pool token
    /// @param _oracleManager The address of the oracle manager
    /// @param _projectedAPY The projected APY of the pool
    /// @param _poolSize The size of the pool
    function createPool(
        string calldata _poolName,
        string calldata _poolSymbol,
        string calldata _fundManagerLenderId,
        address _poolManager,
        address _poolToken,
        address _oracleManager,
        uint256 _projectedAPY,
        uint256 _poolSize
    ) external onlyRole(DEFAULT_ADMIN_ROLE) returns (address _poolAddress, address _fundManager) {
        if(!isPoolManager[_poolManager]) {
            revert InvalidAddress(_poolManager);
        }
        if(!isWhitelistedToken[_poolToken]) {
            revert InvalidAddress(_poolToken);
        }
        if(isPoolNameUsed[_poolName]) {
            revert InvalidPoolName(_poolName);
        }
        _fundManager = address(new ERC1967Proxy(
                fundManagerImplementation,
                ""
            )
        );
        _poolAddress = address(new ERC1967Proxy(
            poolImplementation,
            abi.encodeWithSelector(
                CsigmaV2Pool.initialize.selector,
                string(abi.encodePacked("c", _poolName)),
                string(abi.encodePacked("c", _poolSymbol)),
                _poolManager,
                _fundManager,
                _poolToken,
                _oracleManager,
                _projectedAPY,
                _poolSize
            )));
        CsigmaV2FundManager(_fundManager).initialize(_poolToken, diamondV1, _fundManagerLenderId, _poolAddress);
        pools.push(_poolAddress);
        isPoolNameUsed[_poolName] = true;
        emit PoolCreated(_poolAddress, _poolManager, _fundManager, _poolToken, _oracleManager, _projectedAPY, _poolSize);
    }

    /// @notice Creates a new staking pool
    /// @param _pool The address of the pool for which the staking pool is to be created
    function createStakingPool(address _pool) external onlyRole(DEFAULT_ADMIN_ROLE) returns (address _stakingPool) {
        if(isStakingPoolCreated[_pool]) {
            revert StakingPoolExist(_pool);
        }
        _stakingPool = address(new ERC1967Proxy(stakingPoolImplementation, abi.encodeWithSelector(CsigmaV2StakingPool.initialize.selector, _msgSender(), _pool, sigmaToken)));
        isStakingPoolCreated[_pool] = true;
        emit StakingPoolCreated(_stakingPool, _pool);
    }

    /// @notice Updates the pool manager of a pool
    /// @param _pool The address of the pool whose pool manager is to be updated
    function updatePoolManager(address _pool, address _poolManager) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if(!isPoolManager[_poolManager]) {
            revert InvalidAddress(_poolManager);
        }
        emit PoolManagerUpdated(_pool, CsigmaV2Pool(_pool).poolManager(), _poolManager);
        CsigmaV2Pool(_pool).updatePoolManager(_poolManager);
    }

    /// @notice Updates the pool size of a pool
    /// @param _pool The address of the pool whose pool size is to be updated
    function updatePoolSize(address _pool, uint256 _poolSize) external onlyRole(DEFAULT_ADMIN_ROLE) {
        emit PoolSizeUpdated(_pool, CsigmaV2Pool(_pool).poolSize(), _poolSize);
        CsigmaV2Pool(_pool).updatePoolSize(_poolSize);
    }

    /// @notice Updates the pool investment limit
    /// @param _pool The address of the pool whose investment limit is to be updated
    function updatePoolInvestmentLimit(address _pool, uint256 _limit) external onlyRole(DEFAULT_ADMIN_ROLE) {
        CsigmaV2Pool(_pool).updateMinimumInvestmentLimit(_limit);
    }

    /// @notice Updates the status of the pool to closed
    /// @param _pool The address of the pool whose status is to be updated to closed
    function closePool(address _pool) external onlyRole(DEFAULT_ADMIN_ROLE) {
        CsigmaV2Pool(_pool).closePool();
    }

    /// @notice Adds a new oracle manager to a pool
    /// @param _pool The address of the pool to which the oracle manager is to be added
    function addOracleManager(address _pool, address _manager) external onlyRole(DEFAULT_ADMIN_ROLE) {
        CsigmaV2Pool(_pool).addOracleManager(_manager);
    }

    /// @notice Removes an oracle manager from a pool
    /// @param _pool The address of the pool from which the oracle manager is to be removed
    function removeOracleManager(address _pool, address _manager) external onlyRole(DEFAULT_ADMIN_ROLE) {
        CsigmaV2Pool(_pool).removeOracleManager(_manager);
    }

    /// @notice Updates the implementation of a proxy which maybe a pool,staking pool or fund manager
    /// @param _target The address of the proxy
    /// @param _implementation The address of the new implementation
    function upgradeTarget(address _target, address _implementation) external onlyRole(DEFAULT_ADMIN_ROLE) {
        UUPSUpgradeable(_target).upgradeTo(_implementation);
    }
    
    /// @notice Pauses a target contract
    /// @param _target The address of the target contract
    function pauseTarget(address _target) external onlyRole(DEFAULT_ADMIN_ROLE) {
        AccessControl(_target).pause();
    }

    /// @notice Unpauses a target contract
    /// @param _target The address of the target contract
    function unpauseTarget(address _target) external onlyRole(DEFAULT_ADMIN_ROLE) {
        AccessControl(_target).unpause();
    }

    /// @notice Withdraws tokens from a target contract
    /// @param _target The address of the target contract
    function emergencyWithdraw(address _target, address _token, address _to, uint256 _amount) external onlyRole(DEFAULT_ADMIN_ROLE) {
        AccessControl(_target).emergencyWithdraw(_token, _to, _amount);
    }

    /// @notice Grants a role to an account in a target contract
    /// @param _target The address of the target contract
    /// @param role The role to be granted
    /// @param _account The address of the account to which the role is to be granted
    function grantRoleTarget(address _target, bytes32 role, address _account) external onlyRole(DEFAULT_ADMIN_ROLE) {
        AccessControl(_target).grantRole(role, _account);
    }

    /// @notice Revokes a role from an account in a target contract
    /// @param _target The address of the target contract
    /// @param role The role to be revoked
    /// @param _account The address of the account from which the role is to be revoked
    function revokeRoleTarget(address _target, bytes32 role, address _account) external onlyRole(DEFAULT_ADMIN_ROLE) {
        AccessControl(_target).revokeRole(role, _account);
    }

    /// @notice Transfers the admin role to a new account
    /// @param _newOwner The address of the new admin
    function transferAdmin(address _newOwner) public {
        grantRole(DEFAULT_ADMIN_ROLE, _newOwner);
        revokeRole(DEFAULT_ADMIN_ROLE, _msgSender());
        emit AdminTransferred(_msgSender(), _newOwner);
    }    

    /// @notice Adds a particular role on the current contract
    /// @param role The role to be added
    /// @param _account The address of the account to which the role is to be added
    function grantRole(bytes32 role, address _account)
        public
        virtual
        override
        onlyRole(getRoleAdmin(role))
    {
        _grantRole(role, _account);
    }

    /// @notice Revokes a particular role on the current contract
    /// @param role The role to be revoked
    /// @param _account The address of the account from which the role is to be revoked
    function revokeRole(bytes32 role, address _account)
        public
        override
        onlyRole(getRoleAdmin(role))
    {
        _revokeRole(role, _account);
    }

    /// @notice Upgrades the implementation of the contract
    /// @dev ensures that the caller is admin by using onlyRole modifier
    /// @param _newImplementation The address of the new implementation
    function _authorizeUpgrade(address _newImplementation)
        internal
        override
        onlyRole(DEFAULT_ADMIN_ROLE)
    {}
}","keccak256":"0xca1a1b86173607f4e42f0b3fb9c59e2dae96a204a495ff976810532d1eb1bbfc","license":"BUSL-1.1"},"contracts/v2/CsigmaV2FundManager.sol":{"content":"// SPDX-License-Identifier: BUSL-1.1
// @author cSigma Finance Inc., a Delaware company, for its Real World Credit tokenization protocol

pragma solidity 0.8.9;

import "@openzeppelin/contracts-upgradeable/access/AccessControlUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/security/PausableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/token/ERC20/utils/SafeERC20Upgradeable.sol";
import "../interfaces/ICsigmaV1.sol";
import "./CsigmaV2Pool.sol";

error V1PoolIsNotActive(string _poolId);
error InvalidV1Pool(string _poolId);
error InvalidAllocation(uint256 _allocation);
error InvalidV1Amount(uint256 _v1Amount);
error InvalidAmount(uint256 _v2Amount, uint256 _v1Amount);
error DuplicatePool(string _poolId);

/// @title CsigmaV2FundManager
/// @notice This contract manages the fund deployment and claim process for the cSigma V2 Pool Managers
contract CsigmaV2FundManager is
    Initializable,
    AccessControlUpgradeable,
    UUPSUpgradeable,
    PausableUpgradeable
{
    address public factory;
    address public pool;
    address public poolToken;
    address public diamondV1;
    uint16 public totalAllocation;
    string public fundManagerLenderId;
    PoolInfo[] public v1Pools;
    mapping (string => bool) private _isUsed;

    /// @notice PoolInfo struct to store the V1 pool information
    /// @param v1PoolId The V1 pool ID
    /// @param allocation The allocation percentage of the pool
    struct PoolInfo {
        string v1PoolId;
        uint16 allocation;
    }

    /// @notice Claim struct to store the claim information
    /// @param request The V1 request
    /// @param sigR The R value of the signature
    /// @param sigS The S value of the signature
    /// @param sigV The V value of the signature
    struct Claim {
        ICsigmaV1.Request request;
        bytes32 sigR;
        bytes32 sigS;
        uint8 sigV;
    }

    /// @notice Disburse struct to store the disburse information
    /// @param v1PoolIndex The index of the V1 pool
    /// @param amount The amount to disburse
    struct Disburse {
        uint256 v1PoolIndex;
        uint256 amount;
    }

    event AdminTransferred(address _oldOwner, address _newOwner);
    event V1PoolAdded(address indexed _executor, uint16 _allocation, string _v1PoolId);
    event V1PoolRemoved(address indexed _executor, uint16 _allocation, string _v1PoolId);
    event V1PoolAllocationUpdated(
        address indexed _executor,
        uint16 _prevAllocation,
        uint16 _newAllocation,
        string _v1PoolId
    );
    event FundDeployed(address indexed _executor, uint256 _amount);
    event FundClaimed(address indexed _executor, uint256 _amount);
    event EmergencyWithdraw(address _token, address _to, uint256 _amount);

    modifier notZeroAddress(address _account) {
        require(_account != address(0), "address cannot be zero");
        _;
    }

    modifier onlyPoolManager() {
        if(_msgSender() != CsigmaV2Pool(pool).poolManager()) {
            revert AccessDenied(_msgSender());
        }
        _;
    }

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    /// @notice Initializes the contract with the required parameters
    /// @param _poolToken The address of the pool token
    /// @param _diamondV1 The address of the V1 diamond
    /// @param _lenderId The lender ID of the fund manager
    /// @param _pool The address of the V2 pool
    function initialize(
        address _poolToken,
        address _diamondV1,
        string calldata _lenderId,
        address _pool
    )
        public
        initializer
    {
        __AccessControl_init();
        __UUPSUpgradeable_init();
        __Pausable_init();

        _grantRole(DEFAULT_ADMIN_ROLE, _msgSender());
        factory = _msgSender();
        poolToken = _poolToken;
        diamondV1 = _diamondV1;
        fundManagerLenderId = _lenderId;
        pool = _pool;
        SafeERC20Upgradeable.forceApprove(IERC20Upgradeable(_poolToken), _diamondV1, type(uint256).max);
    }

    /// @notice Returns the total number of V1 pools to which the funds are deployed
    function totalV1Pools() external view returns (uint256) {
        return v1Pools.length;
    }

    /// @notice Returns the total assets under management
    function totalAssets() public view virtual returns (uint256) {
        return (IERC20Upgradeable(poolToken).balanceOf(address(this)) + ICsigmaV1(diamondV1).getTokenBalance(fundManagerLenderId, poolToken));
    }

    /// @notice Adds a new V1 pool to the fund manager
    /// @dev Only the pool manager can call this function
    /// @param _v1PoolId The V1 pool ID
    /// @param _allocation The allocation percentage of the pool
    function addPool(string calldata _v1PoolId, uint16 _allocation) external onlyPoolManager whenNotPaused {
        if(_isUsed[_v1PoolId]) revert DuplicatePool(_v1PoolId);
        if(ICsigmaV1(diamondV1).getCreditPoolStatus(_v1PoolId) != ICsigmaV1.CreditPoolStatus.ACTIVE) {
            revert V1PoolIsNotActive(_v1PoolId);
        }
        if(ICsigmaV1(diamondV1).getPoolToken(_v1PoolId) != poolToken) {
            revert InvalidV1Pool(_v1PoolId);
        }
        if(_allocation + totalAllocation > 10000) {
            revert InvalidAllocation(_allocation);
        }
        v1Pools.push(PoolInfo(_v1PoolId, _allocation));
        totalAllocation += _allocation;
        _isUsed[_v1PoolId] = true;
        emit V1PoolAdded(_msgSender(), _allocation, _v1PoolId); 
    }

    /// @notice Removes a V1 pool from the fund manager
    /// @dev Only the pool manager can call this function
    /// @param _index The index of the V1 pool
    function removePool(uint256 _index) external onlyPoolManager whenNotPaused {
        uint256 _lastIndex = v1Pools.length - 1;
        PoolInfo memory _pool = v1Pools[_index];
        if(_index != _lastIndex) {
            v1Pools[_index] = v1Pools[_lastIndex];
        }
        v1Pools.pop();
        _isUsed[_pool.v1PoolId] = false;
        totalAllocation -= _pool.allocation;
        emit V1PoolRemoved(_msgSender(), _pool.allocation, _pool.v1PoolId);
    }

    /// @notice Updates the allocation of a V1 pool
    /// @dev Only the pool manager can call this function
    /// @param _index The index of the V1 pool
    /// @param _allocation The new allocation percentage of the pool
    function updatePoolAllocation(uint256 _index, uint16 _allocation) external onlyPoolManager whenNotPaused {
        PoolInfo memory _pool = v1Pools[_index];
        if(((_allocation + totalAllocation) - _pool.allocation) > 10000) {
            revert InvalidAllocation(_allocation);
        }
        v1Pools[_index].allocation = _allocation; 
        totalAllocation = (_allocation + totalAllocation) - _pool.allocation;
        emit V1PoolAllocationUpdated(_msgSender(), _pool.allocation, _allocation, _pool.v1PoolId);
    }

    /// @notice Deploys the funds to the V1 pools
    /// @dev Only the pool manager can call this function
    function deployFunds() external onlyPoolManager whenNotPaused {
        if(totalAllocation != 10000) revert InvalidAllocation(totalAllocation);
        uint256 _bal = IERC20Upgradeable(poolToken).balanceOf(address(this));
        ICsigmaV1(diamondV1).deposit(fundManagerLenderId, poolToken, _bal);
        uint256 _amount;
        uint256 _deployed;
        for(uint i; i < v1Pools.length; i++) {
            _amount = (_bal * v1Pools[i].allocation) / 10000;
            _deployed += _amount;
            ICsigmaV1(diamondV1).invest(fundManagerLenderId, v1Pools[i].v1PoolId, _amount);
        }
        CsigmaV2Pool(pool).updateAssetUnderManagement(CsigmaV2Pool(pool).assetUnderManagement() + _deployed);
        emit FundDeployed(_msgSender(), _bal);
    }

    /// @notice Claims the funds from the V1 pools
    /// @dev Only the pool manager can call this function
    /// @param _claim The claim information
    function claimFunds(Claim[] calldata _claim) external onlyPoolManager whenNotPaused {
        uint256 _initial = ICsigmaV1(diamondV1).getTokenBalance(fundManagerLenderId, poolToken);
        for(uint i; i < _claim.length; i++) {
            ICsigmaV1(diamondV1).withdrawPoolPaymentIntoVault(
                _claim[i].request,
                _claim[i].sigR,
                _claim[i].sigS,
                _claim[i].sigV
            );
        }
        uint256 _recouped = ICsigmaV1(diamondV1).getTokenBalance(fundManagerLenderId, poolToken);
        CsigmaV2Pool(pool).updateAssetUnderManagement(CsigmaV2Pool(pool).assetUnderManagement() - (_recouped - _initial));
        ICsigmaV1(diamondV1).withdrawRequest(fundManagerLenderId, poolToken, _recouped);
        emit FundClaimed(_msgSender(), _recouped);
    }
    
    /// @notice Sends the funds to the V2 pool reserve
    /// @dev Only the pool manager can call this function
    /// @param _v2Amount The amount to send to the V2 pool reserve
    function sendToV2Reserve(uint256 _v2Amount) external onlyPoolManager whenNotPaused {
        SafeERC20Upgradeable.safeTransfer(IERC20Upgradeable(poolToken), pool, _v2Amount);
    }

    /// @notice Pauses the contract
    /// @dev Only the admin can call this function
    function pause() external onlyRole(DEFAULT_ADMIN_ROLE) {
        _pause();
    }

    /// @notice Unpauses the contract
    /// @dev Only the admin can call this function
    function unpause() external onlyRole(DEFAULT_ADMIN_ROLE) {
        _unpause();
    }

    /// @notice Withdraws the funds from the contract
    /// @dev Only the admin can call this function
    /// @param _token The address of the token
    /// @param _to The address to which the funds are withdrawn
    /// @param _amount The amount to withdraw
    function emergencyWithdraw(address _token, address _to, uint256 _amount) external onlyRole(DEFAULT_ADMIN_ROLE) {
        SafeERC20Upgradeable.safeTransfer(IERC20Upgradeable(_token), _to, _amount);
        emit EmergencyWithdraw(_token, _to, _amount);
    }

    /// @notice Transfers the admin role to a new address
    /// @param _newOwner The address of the new admin
    function transferAdmin(address _newOwner) public
    {
        grantRole(DEFAULT_ADMIN_ROLE, _newOwner);
        revokeRole(DEFAULT_ADMIN_ROLE, _msgSender());
        emit AdminTransferred(_msgSender(), _newOwner);
    }    

    /// @notice Grants the given role to the account
    /// @param role The role to grant
    /// @param _account The address to which the role is granted
    function grantRole(bytes32 role, address _account)
        public
        virtual
        override
        onlyRole(getRoleAdmin(role))
        notZeroAddress(_account)
        whenNotPaused
    {
        _grantRole(role, _account);
    }

    /// @notice Revokes the given role from the account
    /// @param role The role to revoke
    /// @param _account The address from which the role is revoked
    function revokeRole(bytes32 role, address _account)
        public
        override
        onlyRole(getRoleAdmin(role))        
        notZeroAddress(_account)        
        whenNotPaused
    {
        _revokeRole(role, _account);
    }

    /// @notice Upgrades the contract to a new implementation
    /// @dev Only the admin can call this function
    /// @param _newImplementation The address of the new implementation
    function _authorizeUpgrade(address _newImplementation)
        internal
        override
        onlyRole(DEFAULT_ADMIN_ROLE)
    {}
}","keccak256":"0x7374f1e1e19d00d12aba1efd5bb95c24fb955e54d9d877821936fc5578654960","license":"BUSL-1.1"},"contracts/v2/CsigmaV2Pool.sol":{"content":"// SPDX-License-Identifier: BUSL-1.1
// @author cSigma Finance Inc., a Delaware company, for its Real World Credit tokenization protocol

pragma solidity 0.8.9;

import "@openzeppelin/contracts-upgradeable/access/AccessControlUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/security/PausableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/token/ERC20/extensions/ERC4626Upgradeable.sol";
import "./CsigmaV2Factory.sol";

error PoolIsNotActive();
error InvalidPoolSize(uint256 _poolSize);
error InvalidStatusUpdate();
error AccessDenied(address _executor);
error WithdrawalPending();
error InvalidDepositAmount(uint256 _assets);

/// @title SactionList
/// @notice This interface is used to check if the user is sanctioned
interface SanctionsList {
    function isSanctioned(address addr) external view returns (bool);
}

/// @title FundManager
/// @notice This interface is used to get the total assets managed by the fund manager
interface FundManager {
    function totalAssets() external view returns (uint256);
}

/// @title CsigmaV2Pool
/// @notice This contract is used to manage the pool
contract CsigmaV2Pool is
    Initializable,
    AccessControlUpgradeable,
    UUPSUpgradeable,
    PausableUpgradeable,
    ERC4626Upgradeable
{
    bytes32 public constant ROLE_ORACLE_MANAGER = keccak256("ROLE_ORACLE_MANAGER");
    address public factory;
    address public poolManager;
    address public fundManager;
    address public poolToken;
    PoolStatus public status;
    uint256 public projectedAPY;
    uint256 public poolSize;
    uint256 public assetUnderManagement;
    uint256 public suppliedAPY;
    uint256 public minimumInvestmentLimit;

    enum PoolStatus {PENDING, ACTIVE, CLOSE}
    
    event OracleManagerAdded(address _account);
    event OracleManagerRemoved(address _account);
    event AdminTransferred(address _oldOwner, address _newOwner);
    event PoolStatusUpdated(address indexed _by, PoolStatus _prevStatus, PoolStatus _newStatus);
    event AssetUnderManagementUpdated(address indexed _by, uint256 _prevValue, uint256 _newValue);
    event SuppliedAPYUpdated(address indexed _by, uint256 _prevValue, uint256 _newValue);
    event MinimumInvestmentLimitUpdated(address indexed _by, uint256 _prevValue, uint256 _newValue);
    event EmergencyWithdraw(address _token, address _to, uint256 _amount);

    modifier whenNotSanctioned(address _user) {
        if(SanctionsList(CsigmaV2Factory(factory).chainalysis()).isSanctioned(_user)) {
            revert AccessDenied(_user);
        }
        _;
    }
    
    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    /// @notice This function is used to initialize the contract
    /// @param _poolName The name of the pool
    /// @param _poolSymbol The symbol of the pool
    /// @param _poolManager The address of the pool manager
    /// @param _fundManager The address of the fund manager
    /// @param _poolToken The address of the pool token
    /// @param _oracleManager The address of the oracle manager
    /// @param _projectedAPY The projected APY
    /// @param _poolSize The size of the pool
    function initialize(
        string calldata _poolName,
        string calldata _poolSymbol,
        address _poolManager,
        address _fundManager,
        address _poolToken,
        address _oracleManager,
        uint256 _projectedAPY,
        uint256 _poolSize
    )
        public
        initializer
    {
        __AccessControl_init();
        __UUPSUpgradeable_init();
        __Pausable_init();
        __ERC4626_init(IERC20Upgradeable(_poolToken));
        __ERC20_init(_poolName, _poolSymbol);

        _grantRole(DEFAULT_ADMIN_ROLE, _msgSender());
        _grantRole(ROLE_ORACLE_MANAGER, _oracleManager);
        _grantRole(ROLE_ORACLE_MANAGER, _fundManager);
        factory = _msgSender();
        poolManager = _poolManager;
        fundManager = _fundManager;
        poolToken = _poolToken;
        projectedAPY = _projectedAPY;
        poolSize = _poolSize;
    }

    /// @notice This function is used to get the total amount of the underlying asset that is “managed” by Vault
    /// @return The total assets
    function totalAssets() public view virtual override returns (uint256) {
        return (IERC20Upgradeable(poolToken).balanceOf(address(this)) + FundManager(fundManager).totalAssets() + assetUnderManagement);
    }

    /// @notice This function returns the maximum deposit amount
    /// @return The maximum deposit amount
    function maxDeposit(address) public view virtual override returns (uint256) {
        return (poolSize - assetUnderManagement);
    }

    /// @notice This function returns the maximum amount of shares that can be minted
    /// @return The maximum amount of shares
    function maxMint(address) public view virtual override returns (uint256) {
        return previewDeposit(poolSize - assetUnderManagement);
    }

    /// @notice This function returns the maximum amount of assets that can be withdrawn
    /// @return The maximum amount of assets
    function maxWithdraw(address) public view virtual override returns (uint256) {
        return IERC20Upgradeable(poolToken).balanceOf(address(this));
    }

    /// @notice This function returns the maximum amount of shares that can be redeemed
    /// @return The maximum amount of shares
    function maxRedeem(address) public view virtual override returns (uint256) {
        return _convertToShares(maxWithdraw(address(0)), MathUpgradeable.Rounding.Down);
    }

    /// @notice This function is used to deposit the assets
    /// @param assets The amount of assets to deposit
    /// @param receiver The address of the receiver
    /// @return shares The amount of shares minted
    function deposit(uint256 assets, address receiver) public virtual override whenNotSanctioned(_msgSender()) returns (uint256 shares) {
        if(status != PoolStatus.ACTIVE) revert PoolIsNotActive();
        if(assets < minimumInvestmentLimit) revert InvalidDepositAmount(assets);
        shares = super.deposit(assets, receiver);
        SafeERC20Upgradeable.safeTransfer(IERC20Upgradeable(poolToken), fundManager, (assets * 9000) / 10000);
    }

    /// @notice This function is used to mint the shares
    /// @param shares The amount of shares to mint
    /// @param receiver The address of the receiver
    /// @return assets The amount of assets used to mint the shares
    function mint(uint256 shares, address receiver) public virtual override whenNotSanctioned(_msgSender()) returns (uint256 assets) {
        if(status != PoolStatus.ACTIVE) revert PoolIsNotActive();
        assets = super.mint(shares, receiver);
        if(assets < minimumInvestmentLimit) revert InvalidDepositAmount(assets);
        SafeERC20Upgradeable.safeTransfer(IERC20Upgradeable(poolToken), fundManager, (assets * 9000) / 10000);
    }

    /// @notice This function is used to withdraw the assets
    /// @param assets The amount of assets to withdraw
    /// @param receiver The address of the receiver
    /// @param owner The address of the owner of the assets
    /// @return The amount of shares burned
    function withdraw(uint256 assets, address receiver, address owner) public virtual override whenNotSanctioned(_msgSender()) returns (uint256) {
        if(status != PoolStatus.ACTIVE) revert PoolIsNotActive();
        return super.withdraw(assets, receiver, owner);
    }

    /// @notice This function is used to redeem the shares
    /// @param shares The amount of shares to redeem
    /// @param receiver The address of the receiver
    /// @param owner The address of the owner of the shares
    /// @return The amount of assets redeemed
    function redeem(uint256 shares, address receiver, address owner) public virtual override whenNotSanctioned(_msgSender()) returns (uint256) {
        if(status != PoolStatus.ACTIVE) revert PoolIsNotActive();
        return super.redeem(shares, receiver, owner);
    }

    /// @notice This function is used to update the pool manager
    /// @dev Only the admin can call this function
    /// @param _poolManager The address of the new pool manager
    function updatePoolManager(address _poolManager) external onlyRole(DEFAULT_ADMIN_ROLE) {
        poolManager = _poolManager;
    }

    /// @notice This function is used to update the size limit of the pool
    /// @dev Only the admin can call this function
    /// @param _poolSize The new size limit of the pool
    function updatePoolSize(uint256 _poolSize) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if(_poolSize < assetUnderManagement) revert InvalidPoolSize(_poolSize);
        poolSize = _poolSize;
    }

    /// @notice This function is used to update the minimum investment limit
    /// @dev Only the admin or pool manager can call this function
    /// @param _min The new minimum investment limit
    function updateMinimumInvestmentLimit(uint256 _min) external {
        require(_msgSender() == poolManager || hasRole(DEFAULT_ADMIN_ROLE, _msgSender()), "Access Denied");
        emit MinimumInvestmentLimitUpdated(_msgSender(), minimumInvestmentLimit, _min);
        minimumInvestmentLimit = _min;
    }

    /// @notice This function is used to update the status of the pool from pending to active
    /// @dev Only the pool manager can call this function
    function activatePool() external whenNotPaused {
        if(status != PoolStatus.PENDING) revert InvalidStatusUpdate();
        if(_msgSender() != poolManager) revert AccessDenied(_msgSender());
        status = PoolStatus.ACTIVE;
        emit PoolStatusUpdated(_msgSender(), PoolStatus.PENDING, PoolStatus.ACTIVE);
    }

    /// @notice This function is used to update the status of the pool to close
    /// @dev Only the admin can call this function
    function closePool() external onlyRole(DEFAULT_ADMIN_ROLE) {
        if(status == PoolStatus.CLOSE) revert InvalidStatusUpdate();
        if(totalAssets() != 0 && totalSupply() != 0)  revert WithdrawalPending();
        emit PoolStatusUpdated(_msgSender(), status, PoolStatus.CLOSE);
        status = PoolStatus.CLOSE;
    }

    /// @notice This function is used to update the AUM of the pool
    /// @dev Only the oracle manager can call this function
    /// @param _assetUnderManagement The new AUM
    function updateAssetUnderManagement(uint256 _assetUnderManagement) external onlyRole(ROLE_ORACLE_MANAGER) {
        if(status != PoolStatus.ACTIVE) revert PoolIsNotActive();
        emit AssetUnderManagementUpdated(_msgSender(), assetUnderManagement, _assetUnderManagement);
        assetUnderManagement = _assetUnderManagement;
    }

    /// @notice This function is used to update the supplied APY
    /// @dev Only the oracle manager can call this function
    /// @param _apy The new APY
    function updateSuppliedAPY(uint256 _apy) external onlyRole(ROLE_ORACLE_MANAGER) {
        if(status != PoolStatus.ACTIVE) revert PoolIsNotActive();
        emit SuppliedAPYUpdated(_msgSender(), suppliedAPY, _apy);
        suppliedAPY = _apy;
    }

    /// @notice This function is used to update the AUM and APY of the pool
    /// @dev Only the oracle manager can call this function
    /// @param _assetUnderManagement The new AUM
    /// @param _apy The new APY
    function updateAssetAndAPY(uint256 _assetUnderManagement, uint256 _apy) external onlyRole(ROLE_ORACLE_MANAGER) {
        if(status != PoolStatus.ACTIVE) revert PoolIsNotActive();
        emit AssetUnderManagementUpdated(_msgSender(), assetUnderManagement, _assetUnderManagement);
        assetUnderManagement = _assetUnderManagement;
        emit SuppliedAPYUpdated(_msgSender(), suppliedAPY, _apy);
        suppliedAPY = _apy;
    }

    /// @notice This function is used to check if the account is an oracle manager
    /// @param _account The address of the account
    function isOracleManager(address _account) public view returns (bool) {
        return hasRole(ROLE_ORACLE_MANAGER, _account);
    }

    /// @notice Pauses the contract
    /// @dev Only the admin can call this function
    function pause() external onlyRole(DEFAULT_ADMIN_ROLE) {
        _pause();
    }

    /// @notice Unpauses the contract
    /// @dev Only the admin can call this function
    function unpause() external onlyRole(DEFAULT_ADMIN_ROLE) {
        _unpause();
    }

    /// @notice Adds an oracle manager
    /// @dev Only the admin can call this function
    /// @param _account The address of the oracle manager
    function addOracleManager(address _account) public onlyRole(DEFAULT_ADMIN_ROLE) {
        grantRole(ROLE_ORACLE_MANAGER, _account);
        emit OracleManagerAdded(_account);
    }

    /// @notice Removes an oracle manager
    /// @dev Only the admin can call this function
    /// @param _account The address of the oracle manager
    function removeOracleManager(address _account) public onlyRole(DEFAULT_ADMIN_ROLE) {
        revokeRole(ROLE_ORACLE_MANAGER, _account);
        emit OracleManagerRemoved(_account);
    }

    /// @notice Withdraws the funds from the contract
    /// @dev Only the admin can call this function
    /// @param _token The address of the token
    /// @param _to The address to which the funds are withdrawn
    /// @param _amount The amount to withdraw
    function emergencyWithdraw(address _token, address _to, uint256 _amount) external onlyRole(DEFAULT_ADMIN_ROLE) {
        SafeERC20Upgradeable.safeTransfer(IERC20Upgradeable(_token), _to, _amount);
        emit EmergencyWithdraw(_token, _to, _amount);
    }

    /// @notice Transfers the admin role to a new address
    /// @param _newOwner The address of the new admin
    function transferAdmin(address _newOwner) public {
        grantRole(DEFAULT_ADMIN_ROLE, _newOwner);
        revokeRole(DEFAULT_ADMIN_ROLE, _msgSender());
        emit AdminTransferred(_msgSender(), _newOwner);
    }    

    /// @notice Grants the given role to the account
    /// @param role The role to grant
    /// @param _account The address to which the role is granted
    function grantRole(bytes32 role, address _account)
        public
        virtual
        override
        onlyRole(getRoleAdmin(role))
        whenNotPaused
    {
        _grantRole(role, _account);
    }

    /// @notice Revokes the given role from the account
    /// @param role The role to revoke
    /// @param _account The address from which the role is revoked
    function revokeRole(bytes32 role, address _account)
        public
        override
        onlyRole(getRoleAdmin(role))        
        whenNotPaused
    {
        _revokeRole(role, _account);
    }

    function _beforeTokenTransfer(
        address _from,
        address _to,
        uint256 _amount
    )
        internal
        override
        whenNotPaused
        whenNotSanctioned(_from)
        whenNotSanctioned(_to)
    {
        super._beforeTokenTransfer(_from, _to, _amount);
    }

    /// @notice Upgrades the contract to a new implementation
    /// @dev Only the admin can call this function
    /// @param _newImplementation The address of the new implementation
    function _authorizeUpgrade(address _newImplementation)
        internal
        override
        onlyRole(DEFAULT_ADMIN_ROLE)
    {}
}","keccak256":"0x2c65b74dcf79972db15d65512da90684f7daa55f070af6ea60c7881fefbb7f4e","license":"BUSL-1.1"},"contracts/v2/CsigmaV2StakingPool.sol":{"content":"// SPDX-License-Identifier: BUSL-1.1
// @author cSigma Finance Inc., a Delaware company, for its Real World Credit tokenization protocol

pragma solidity 0.8.9;

import "@openzeppelin/contracts-upgradeable/access/AccessControlUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/token/ERC20/utils/SafeERC20Upgradeable.sol";
import "@openzeppelin/contracts-upgradeable/token/ERC20/extensions/IERC20MetadataUpgradeable.sol";
import "./CsigmaV2Pool.sol";

error InvalidInputs(uint256 _amount, uint32 _lockingPeriodInSeconds);
error AlreadyStaked(address _staker);
error NotStaked(address _staker);
error NotUnlocked(address _staker);

/// @title CsigmaV2StakingPool
/// @notice This contract is used to stake assets in the pool and earn rewards
contract CsigmaV2StakingPool is
    Initializable,
    AccessControlUpgradeable,
    UUPSUpgradeable
{
    address public factory;
    address public stakingToken;
    address public rewardToken;
    uint32 public slice;
    uint32 public maxStakeDurationAllowed;
    uint32 public minStakeDurationAllowed;
    PoolStatus public status;
    uint256 public rewardRate;
    uint256 public totalRewards;
    mapping(address => StakeInfo) public stakes;
    mapping(uint256 => uint256) public payableRewards;

    /// @notice This struct is used to store the stake information
    /// @param amount The amount of staking token staked
    /// @param rewards The rewards earned by the staker
    /// @param unlockTime The time when the staker can unstake the assets
    struct StakeInfo {
        uint256 amount;
        uint256 rewards;
        uint32 unlockTime;        
    }
    
    enum PoolStatus {PENDING, ACTIVE, CLOSE}

    event AdminTransferred(address _oldOwner, address _newOwner);
    event RewardRateUpdated(uint256 _prevRate, uint256 _newRate);
    event SlicePeriodUpdated(uint32 _prevValue, uint256 _newValue);
    event PoolStatusUpdated(PoolStatus _prevStatus, PoolStatus _newStatus);
    event Staked(address indexed _staker, uint256 _amount, uint256 _assetAmount, uint256 _rewardAmount, uint32 _lockingPeriodInSeconds);
    event Unstaked(address indexed _staker, uint256 _amount, uint256 _rewardAmount);
    event EmergencyWithdraw(address _token, address _to, uint256 _amount);
    event MinMaxStakeDurationUpdated(uint32 _min, uint32 _max, uint32 _newMin, uint32 _newMax);

    modifier notZeroAddress(address _account) {
        require(_account != address(0), "address cannot be zero");
        _;
    }

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    /// @notice This function is used to initialize the contract
    /// @param _admin The address of the admin
    /// @param _stakingToken The address of the staking token
    /// @param _rewardToken The address of the reward token
    function initialize(
        address _admin,
        address _stakingToken,
        address _rewardToken
    )
        public
        initializer
        notZeroAddress(_rewardToken)
    {
        __AccessControl_init();
        __UUPSUpgradeable_init();
        
        _grantRole(DEFAULT_ADMIN_ROLE, _admin);
        factory = _msgSender();
        stakingToken = _stakingToken;
        rewardToken = _rewardToken;
        slice = 30 days;
        minStakeDurationAllowed = 30 days;
        maxStakeDurationAllowed = 180 days;
    }

    function unlockDay(uint32 _unlockTime) public pure returns(uint32) {
        return (_unlockTime / 86400);
    }

    /// @notice This function is used to update the reward rate
    /// @dev Only admin can call this function
    /// @param _rate The new reward rate
    function updateRewardRate(uint256 _rate) external onlyRole(DEFAULT_ADMIN_ROLE) {
        emit RewardRateUpdated(rewardRate, _rate);
        rewardRate = _rate;
    }

    /// @notice This function is used to update the slice period
    /// @dev Only admin can call this function
    /// @param _slice The new slice period
    function updateSlicePeriod(uint32 _slice) external onlyRole(DEFAULT_ADMIN_ROLE) {
        emit SlicePeriodUpdated(slice, _slice);
        slice = _slice;
    }

    /// @notice This function is used to update the reward rate and slice period
    /// @dev Only admin can call this function
    /// @param _rate The new reward rate
    /// @param _slice The new slice period
    function updateRewardInfo(uint256 _rate, uint32 _slice) external onlyRole(DEFAULT_ADMIN_ROLE) {
        emit RewardRateUpdated(rewardRate, _rate);
        rewardRate = _rate;
        emit SlicePeriodUpdated(slice, _slice);
        slice = _slice;
    }

    /// @notice This function is used to update the pool status
    /// @dev Only admin can call this function
    /// @param _status The new pool status
    function updatePoolStatus(PoolStatus _status) external onlyRole(DEFAULT_ADMIN_ROLE) {
        emit PoolStatusUpdated(status, _status);
        status = _status;
    }

    /// @notice This function is used to update the min and max stake duration allowed
    /// @dev Only admin can call this function
    /// @param _min The new min stake duration allowed
    /// @param _max The new max stake duration allowed
    function updateMinMaxDurationAllowed(uint32 _min, uint32 _max) external onlyRole(DEFAULT_ADMIN_ROLE) {
        emit MinMaxStakeDurationUpdated(minStakeDurationAllowed, maxStakeDurationAllowed, _min, _max);
        minStakeDurationAllowed = _min;
        maxStakeDurationAllowed = _max;
    }

    /// @notice This function is used to stake the assets in the pool, users can stake only when they have zero staked amount
    /// @param _amount The amount of staking token to stake
    /// @param _lockingPeriodInSeconds The locking period in seconds
    function stake(uint256 _amount, uint32 _lockingPeriodInSeconds) external {
        if(_amount == 0 || (_lockingPeriodInSeconds % slice != 0) || (_lockingPeriodInSeconds < minStakeDurationAllowed) || (_lockingPeriodInSeconds > maxStakeDurationAllowed)) {
            revert InvalidInputs(_amount, _lockingPeriodInSeconds);
        }
        if(status != PoolStatus.ACTIVE) revert PoolIsNotActive();
        if(stakes[_msgSender()].amount != 0) revert AlreadyStaked(_msgSender());
        SafeERC20Upgradeable.safeTransferFrom(IERC20Upgradeable(stakingToken), _msgSender(), address(this), _amount);
        uint32 _unlockTime = uint32(block.timestamp) + _lockingPeriodInSeconds;
        uint256 _asset = CsigmaV2Pool(stakingToken).convertToAssets(_amount);
        uint256 _reward = (_asset * rewardRate) / (10**IERC20MetadataUpgradeable(CsigmaV2Pool(stakingToken).asset()).decimals());
        uint256 _rewardAmount = (_reward * _lockingPeriodInSeconds) / slice;
        stakes[_msgSender()] = StakeInfo(_amount, _rewardAmount, _unlockTime);
        totalRewards += _rewardAmount;
        payableRewards[unlockDay(_unlockTime)] += _rewardAmount;
        emit Staked(_msgSender(), _amount, _asset, _rewardAmount, _lockingPeriodInSeconds);
    }

    /// @notice This function is used to unstake the enitre staked position from the pool and claim the rewards
    /// @dev Users can unstake only when the assets are unlocked
    function unStake() external {
        if(status != PoolStatus.ACTIVE) revert PoolIsNotActive();
        StakeInfo memory _stake = stakes[_msgSender()];
        if(_stake.amount == 0) revert NotStaked(_msgSender());
        if(block.timestamp < _stake.unlockTime) revert NotUnlocked(_msgSender());
        delete stakes[_msgSender()];
        SafeERC20Upgradeable.safeTransfer(IERC20Upgradeable(stakingToken), _msgSender(), _stake.amount);
        SafeERC20Upgradeable.safeTransfer(IERC20Upgradeable(rewardToken), _msgSender(), _stake.rewards);
        emit Unstaked(_msgSender(), _stake.amount, _stake.rewards);
    }

    /// @notice This function is used to withdraw the assets from the pool in case of emergency
    /// @dev Only admin can call this function
    /// @param _token The address of the token to withdraw
    /// @param _to The address to which the assets should be transferred
    /// @param _amount The amount of assets to withdraw
    function emergencyWithdraw(address _token, address _to, uint256 _amount) external onlyRole(DEFAULT_ADMIN_ROLE) {
